const generateFilePath = (
  routePath: string,
  outDir: string,
  mimeType: string,
  extensionMap?: Record<string, string>
): string => {
  const extension = determineExtension(mimeType, extensionMap)

  let filePath: string
  if (routePath.endsWith(`.${extension}`)) {
    filePath = joinPaths(outDir, routePath)
  } else if (routePath === '/') {
    filePath = joinPaths(outDir, `index.${extension}`)
  } else if (routePath.endsWith('/')) {
    filePath = joinPaths(outDir, routePath, `index.${extension}`)
  } else {
    filePath = joinPaths(outDir, `${routePath}.${extension}`)
  }

  ensureWithinOutDir(outDir, filePath)

  return filePath
}

const parseResponseContent = async (response: Response): Promise<string | ArrayBuffer> => {
  const contentType = response.headers.get('Content-Type')

  try {
    if (contentType?.includes('text') || contentType?.includes('json')) {
      return await response.text()
    } else {
      return await response.arrayBuffer()
    }
  } catch (error) {
    throw new Error(
      `Error processing response: ${error instanceof Error ? error.message : 'Unknown error'}`
    )
  }
}

const determineExtension = (
  mimeType: string,
  userExtensionMap?: Record<string, string>
): string => {
  const extensionMap = userExtensionMap || defaultExtensionMap
  if (mimeType in extensionMap) {
    return extensionMap[mimeType]
  }
  return getExtension(mimeType) || 'html'
}

export const combineBeforeRequestHooks = (
  hooks: BeforeRequestHook | BeforeRequestHook[]
): BeforeRequestHook => {
  if (!Array.isArray(hooks)) {
    return hooks
  }
  return async (req: Request): Promise<Request | false> => {
    let currentReq = req
    for (const hook of hooks) {
      const result = await hook(currentReq)
      if (result === false) {
        return false
      }
      if (result instanceof Request) {
        currentReq = result
      }
    }
    return currentReq
  }
}

export const combineAfterResponseHooks = (
  hooks: AfterResponseHook | AfterResponseHook[]
): AfterResponseHook => {
  if (!Array.isArray(hooks)) {
    return hooks
  }
  return async (res: Response): Promise<Response | false> => {
    let currentRes = res
    for (const hook of hooks) {
      const result = await hook(currentRes)
      if (result === false) {
        return false
      }
      if (result instanceof Response) {
        currentRes = result
      }
    }
    return currentRes
  }
}

export const combineAfterGenerateHooks = (
  hooks: AfterGenerateHook | AfterGenerateHook[],
  fsModule: FileSystemModule,
  options?: ToSSGOptions
): AfterGenerateHook => {
  if (!Array.isArray(hooks)) {
    return hooks
  }
  return async (result: ToSSGResult): Promise<void> => {
    for (const hook of hooks) {
      await hook(result, fsModule, options)
    }
  }
}

export interface SSGPlugin {
  beforeRequestHook?: BeforeRequestHook | BeforeRequestHook[]
  afterResponseHook?: AfterResponseHook | AfterResponseHook[]
  afterGenerateHook?: AfterGenerateHook | AfterGenerateHook[]
}

/**
 * @experimental
 * `fetchRoutesContent` is an experimental feature.
 * The API might be changed.
 */
export const fetchRoutesContent = function* <
  E extends Env = Env,
  S extends Schema = {},
  BasePath extends string = '/',
>(
  app: Hono<E, S, BasePath>,
  beforeRequestHook?: BeforeRequestHook,
  afterResponseHook?: AfterResponseHook,
  concurrency?: number
): Generator<
  Promise<
    | Generator<
        Promise<{ routePath: string; mimeType: string; content: string | ArrayBuffer } | undefined>
      >
    | undefined
  >
> {
  const baseURL = 'http://localhost'
  const pool = createPool({ concurrency })

  for (const route of filterStaticGenerateRoutes(app)) {
    // GET Route Info
    const thisRouteBaseURL = new URL(route.path, baseURL).toString()

    let forGetInfoURLRequest = new Request(thisRouteBaseURL) as AddedSSGDataRequest

    // eslint-disable-next-line no-async-promise-executor
    yield new Promise(async (resolveGetInfo, rejectGetInfo) => {
      try {
        if (beforeRequestHook) {
          const maybeRequest = await beforeRequestHook(forGetInfoURLRequest)
          if (!maybeRequest) {
            resolveGetInfo(undefined)
            return
          }
          forGetInfoURLRequest = maybeRequest as unknown as AddedSSGDataRequest
        }

        await pool.run(() => app.fetch(forGetInfoURLRequest, { [SSG_CONTEXT]: true }))

        if (!forGetInfoURLRequest.ssgParams) {
          if (isDynamicRoute(route.path)) {
            resolveGetInfo(undefined)
            return
          }
          forGetInfoURLRequest.ssgParams = [{}]
        }

        const requestInit = {
          method: forGetInfoURLRequest.method,
          headers: forGetInfoURLRequest.headers,
        }

        resolveGetInfo(
          (function* () {

          forGetInfoURLRequest.ssgParams = [{}]
        }

        const requestInit = {
          method: forGetInfoURLRequest.method,
          headers: forGetInfoURLRequest.headers,
        }

        resolveGetInfo(
          (function* () {
            for (const param of forGetInfoURLRequest.ssgParams as SSGParams) {
              // eslint-disable-next-line no-async-promise-executor
              yield new Promise(async (resolveReq, rejectReq) => {
                try {
                  const replacedUrlParam = replaceUrlParam(route.path, param)
                  let response = await pool.run(() =>
                    app.request(replacedUrlParam, requestInit, {
                      [SSG_CONTEXT]: true,
                    })
                  )
                  if (response.headers.get(X_HONO_DISABLE_SSG_HEADER_KEY)) {
                    resolveReq(undefined)
                    return
                  }
                  if (afterResponseHook) {
                    const maybeResponse = await afterResponseHook(response)
                    if (!maybeResponse) {
                      resolveReq(undefined)
                      return
                    }
                    response = maybeResponse
                  }
                  const mimeType =
                    response.headers.get('Content-Type')?.split(';')[0] || DEFAULT_CONTENT_TYPE
                  const content = await parseResponseContent(response)
                  resolveReq({
                    routePath: replacedUrlParam,
                    mimeType,
                    content,
                  })
                } catch (error) {
                  rejectReq(error)
                }
              })
            }
          })()
        )
      } catch (error) {
        rejectGetInfo(error)
      }
    })
  }
}

export const saveContentToFile = async (
  data: Promise<{ routePath: string; content: string | ArrayBuffer; mimeType: string } | undefined>,
  fsModule: FileSystemModule,
  outDir: string,
  extensionMap?: Record<string, string>
): Promise<string | undefined> => {
  const awaitedData = await data
  if (!awaitedData) {
    return
  }
  const { routePath, content, mimeType } = awaitedData
  const filePath = generateFilePath(routePath, outDir, mimeType, extensionMap)
  const dirPath = dirname(filePath)

  // `dirPath` is empty when outDir itself is the current directory
  if (dirPath !== '' && !createdDirs.has(dirPath)) {
    await fsModule.mkdir(dirPath, { recursive: true })
    createdDirs.add(dirPath)
  }
  if (typeof content === 'string') {
    await fsModule.writeFile(filePath, content)
  } else if (content instanceof ArrayBuffer) {
    await fsModule.writeFile(filePath, new Uint8Array(content))
  }
  return filePath
}

/**
 * @experimental
 * `ToSSGInterface` is an experimental feature.
 * The API might be changed.
 */
export interface ToSSGInterface {
  (
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    app: Hono<any, any, any>,
    fsModule: FileSystemModule,
    options?: ToSSGOptions
  ): Promise<ToSSGResult>
}

/**
 * @experimental
 * `toSSG` is an experimental feature.
 * The API might be changed.
 */
export const toSSG: ToSSGInterface = async (app, fs, options) => {
  let result: ToSSGResult | undefined
  const getInfoPromises: Promise<unknown>[] = []
  const savePromises: Promise<string | undefined>[] = []
  const plugins = options?.plugins || [defaultPlugin()]
  const beforeRequestHooks: BeforeRequestHook[] = []
  const afterResponseHooks: AfterResponseHook[] = []
  const afterGenerateHooks: AfterGenerateHook[] = []
  if (options?.beforeRequestHook) {
    beforeRequestHooks.push(
      ...(Array.isArray(options.beforeRequestHook)
        ? options.beforeRequestHook
        : [options.beforeRequestHook])
    )
  }
  if (options?.afterResponseHook) {
    afterResponseHooks.push(
      ...(Array.isArray(options.afterResponseHook)
        ? options.afterResponseHook
        : [options.afterResponseHook])
    )
  }
  if (options?.afterGenerateHook) {
    afterGenerateHooks.push(
      ...(Array.isArray(options.afterGenerateHook)
        ? options.afterGenerateHook
        : [options.afterGenerateHook])
    )
  }
  for (const plugin of plugins) {
    if (plugin.beforeRequestHook) {
      beforeRequestHooks.push(
        ...(Array.isArray(plugin.beforeRequestHook)
          ? plugin.beforeRequestHook
          : [plugin.beforeRequestHook])
      )
    }
    if (plugin.afterResponseHook) {
      afterResponseHooks.push(
        ...(Array.isArray(plugin.afterResponseHook)
          ? plugin.afterResponseHook
          : [plugin.afterResponseHook])
      )
    }
    if (plugin.afterGenerateHook) {
      afterGenerateHooks.push(
        ...(Array.isArray(plugin.afterGenerateHook)
          ? plugin.afterGenerateHook
          : [plugin.afterGenerateHook])
      )
    }
  }
  try {
    const outputDir = options?.dir ?? DEFAULT_OUTPUT_DIR
    const concurrency = options?.concurrency ?? DEFAULT_CONCURRENCY

      afterGenerateHooks.push(
        ...(Array.isArray(plugin.afterGenerateHook)
          ? plugin.afterGenerateHook
          : [plugin.afterGenerateHook])
      )
    }
  }
  try {
    const outputDir = options?.dir ?? DEFAULT_OUTPUT_DIR
    const concurrency = options?.concurrency ?? DEFAULT_CONCURRENCY

    const combinedBeforeRequestHook = combineBeforeRequestHooks(
      beforeRequestHooks.length > 0 ? beforeRequestHooks : [(req) => req]
    )
    const combinedAfterResponseHook = combineAfterResponseHooks(
      afterResponseHooks.length > 0 ? afterResponseHooks : [(req) => req]
    )
    const getInfoGen = fetchRoutesContent(
      app,
      combinedBeforeRequestHook,
      combinedAfterResponseHook,
      concurrency
    )
    for (const getInfo of getInfoGen) {
      getInfoPromises.push(
        getInfo.then((getContentGen) => {
          if (!getContentGen) {
            return
          }
          for (const content of getContentGen) {
            savePromises.push(
              saveContentToFile(content, fs, outputDir, options?.extensionMap).catch((e) => e)
            )
          }
        })
      )
    }
    await Promise.all(getInfoPromises)
    const files: string[] = []
    for (const savePromise of savePromises) {
      const fileOrError = await savePromise
      if (typeof fileOrError === 'string') {
        files.push(fileOrError)
      } else if (fileOrError) {
        throw fileOrError
      }
    }
    result = { success: true, files }
  } catch (error) {
    const errorObj = error instanceof Error ? error : new Error(String(error))
    result = { success: false, files: [], error: errorObj }
  }
  if (afterGenerateHooks.length > 0) {
    const combinedAfterGenerateHooks = combineAfterGenerateHooks(afterGenerateHooks, fs, options)
    await combinedAfterGenerateHooks(result, fs, options)
  }
  return result
}

/**
 * Get dirname
 * @param path File Path
 * @returns Parent dir path
 */
export const dirname = (path: string): string => {
  const separatedPath = path.split(/[\/\\]/)
  return separatedPath.slice(0, -1).join('/') // Windows supports slash path
}

const normalizePath = (path: string): string => {
  return path.replace(/(\\)/g, '/').replace(/\/$/g, '')
}

const getUncRoot = (path: string): string | undefined => {
  const uncRoot = path.replace(/\\/g, '/').match(/^\/\/([^/]+)\/([^/]+)/)
  if (uncRoot) {
    return `${uncRoot[1].toLowerCase()}/${uncRoot[2].toLowerCase()}`
  }
}

const handleParent = (resultPaths: string[]): void => {
  if (resultPaths.length === 0 || resultPaths[resultPaths.length - 1] === '..') {
    resultPaths.push('..')
  } else {
    resultPaths.pop()
  }
}

const handleNonDot = (path: string, resultPaths: string[]): void => {
  path = path.replace(/^\.(?!.)/, '')
  if (path !== '') {
    resultPaths.push(path)
  }
}

const handleSegments = (paths: string[], resultPaths: string[]): void => {
  for (const path of paths) {
    // Handle `..`
    if (path === '..') {
      handleParent(resultPaths)
    } else {
      // Handle `.` or `abc`
      handleNonDot(path, resultPaths)
    }
  }
}

export const joinPaths = (...paths: string[]): string => {
  const hasUncPrefix = getUncRoot(paths[0]) !== undefined
  paths = paths.map(normalizePath)
  const resultPaths: string[] = []
  handleSegments(paths.join('/').split('/'), resultPaths)
  return (hasUncPrefix ? '//' : paths[0][0] === '/' ? '/' : '') + resultPaths.join('/')
}

interface FilterStaticGenerateRouteData {
  path: string
}

export const filterStaticGenerateRoutes = <E extends Env>(
  hono: Hono<E>
): FilterStaticGenerateRouteData[] => {
  return hono.routes.reduce((acc, { method, handler, path }: RouterRoute) => {
    const targetHandler = findTargetHandler(handler)
    if (['GET', METHOD_NAME_ALL].includes(method) && !isMiddleware(targetHandler)) {
      acc.push({ path })
    }
    return acc
  }, [] as FilterStaticGenerateRouteData[])
}

export const isDynamicRoute = (path: string): boolean => {
  return path.split('/').some((segment) => segment.startsWith(':') || segment.includes('*'))
}

const getPathRoot = (path: string): string => {
  const normalizedPath = path.replace(/\\/g, '/')
  const uncRoot = getUncRoot(normalizedPath)
  if (uncRoot) {
    return `unc:${uncRoot}`
  }

  const driveRoot = normalizedPath.match(/^([A-Za-z]):/)
  if (driveRoot) {
    const kind = normalizedPath[2] === '/' ? 'drive-absolute' : 'drive-relative'
    return `${kind}:${driveRoot[1].toLowerCase()}`
  }

  return normalizedPath.startsWith('/') ? 'absolute' : 'relative'
}

export const ensureWithinOutDir = (outDir: string, filePath: string): void => {
  const outDirSegments = toSegments(joinPaths(outDir))
  const filePathSegments = toSegments(joinPaths(filePath))

  const hasMismatchedPathRoot = getPathRoot(outDir) !== getPathRoot(filePath)

  // `joinPaths` collects every remaining `..` at the head, so a `..` right after
  // the outDir segments means the file path climbs above outDir
  const climbsAboveOutDir = filePathSegments[outDirSegments.length] === '..'

  if (
    hasMismatchedPathRoot ||
    filePathSegments.length <= outDirSegments.length ||
    !outDirSegments.every((segment, i) => segment === filePathSegments[i]) ||
    climbsAboveOutDir
  ) {
    throw new Error(`Path traversal detected: "${filePath}" is outside the output directory`)
  }
}

export interface SSEMessage {
  data: string | Promise<string>
  event?: string
  id?: string
  retry?: number
}

export class SSEStreamingApi extends StreamingApi {
  constructor(writable: WritableStream, readable: ReadableStream) {
    super(writable, readable)
  }

  async writeSSE(message: SSEMessage) {
    const data = await resolveCallback(message.data, HtmlEscapedCallbackPhase.Stringify, false, {})
    const dataLines = (data as string)
      .split(/\r\n|\r|\n/)
      .map((line) => {
        return `data: ${line}`
      })
      .join('\n')

    for (const key of ['event', 'id'] as const) {
      const value = message[key]
      if (value && /[\r\n]/.test(value)) {
        throw new Error(`${key} must not contain "\\r" or "\\n"`)
      }
    }

    const sseData =
      [
        message.event && `event: ${message.event}`,
        dataLines,
        message.id !== undefined && `id: ${message.id}`,
        message.retry !== undefined && `retry: ${message.retry}`,
      ]
        .filter(Boolean)
        .join('\n') + '\n\n'

    await this.write(sseData)
  }
}

const run = async (
  stream: SSEStreamingApi,
  cb: (stream: SSEStreamingApi) => Promise<void>,
  onError?: (e: Error, stream: SSEStreamingApi) => Promise<void>
): Promise<void> => {
  try {
    await cb(stream)
  } catch (e) {
    if (e instanceof Error && onError) {
      await onError(e, stream)

      await stream.writeSSE({
        event: 'error',
        data: e.message,
      })
    } else {
      console.error(e)
    }
  } finally {
    stream.close()
  }
}

export const streamSSE = (
  c: Context,
  cb: (stream: SSEStreamingApi) => Promise<void>,
  onError?: (e: Error, stream: SSEStreamingApi) => Promise<void>
): Response => {
  const { readable, writable } = new TransformStream()
  const stream = new SSEStreamingApi(writable, readable)

  // Until Bun v1.1.27, Bun didn't call cancel() on the ReadableStream for Response objects from Bun.serve()
  if (isOldBunVersion()) {
    c.req.raw.signal.addEventListener('abort', () => {
      if (!stream.closed) {
        stream.abort()
      }
    })
  }

  // in bun, `c` is destroyed when the request is returned, so hold it until the end of streaming
  contextStash.set(stream.responseReadable, c)

  c.header('Transfer-Encoding', 'chunked')
  c.header('Content-Type', 'text/event-stream')
  c.header('Cache-Control', 'no-cache')
  c.header('Connection', 'keep-alive')

  run(stream, cb, onError)

  return c.newResponse(stream.responseReadable)
}

export const stream = (
  c: Context,
  cb: (stream: StreamingApi) => Promise<void>,
  onError?: (e: Error, stream: StreamingApi) => Promise<void>
): Response => {
  const { readable, writable } = new TransformStream()
  const stream = new StreamingApi(writable, readable)

  // Until Bun v1.1.27, Bun didn't call cancel() on the ReadableStream for Response objects from Bun.serve()
  if (isOldBunVersion()) {
    c.req.raw.signal.addEventListener('abort', () => {
      if (!stream.closed) {
        stream.abort()
      }
    })
  }

  // in bun, `c` is destroyed when the request is returned, so hold it until the end of streaming
  contextStash.set(stream.responseReadable, c)
  ;(async () => {
    try {
      await cb(stream)
    } catch (e) {
      if (e === undefined) {
        // If reading is canceled without a reason value (e.g. by StreamingApi)
        // then the .pipeTo() promise will reject with undefined.
        // In this case, do nothing because the stream is already closed.
      } else if (e instanceof Error && onError) {
        await onError(e, stream)
      } else {
        console.error(e)
      }
    } finally {
      stream.close()
    }
  })()

  return c.newResponse(stream.responseReadable)
}

export const streamText = (
  c: Context,
  cb: (stream: StreamingApi) => Promise<void>,
  onError?: (e: Error, stream: StreamingApi) => Promise<void>
): Response => {
  c.header('Content-Type', TEXT_PLAIN)
  c.header('X-Content-Type-Options', 'nosniff')
  c.header('Transfer-Encoding', 'chunked')
  return stream(c, cb, onError)
}

export let isOldBunVersion = (): boolean => {
  // @ts-expect-error @types/bun is not installed
  const version: string = typeof Bun !== 'undefined' ? Bun.version : undefined
  if (version === undefined) {
    return false
  }
  const result = version.startsWith('1.1') || version.startsWith('1.0') || version.startsWith('0.')
  // Avoid running this check on every call
  isOldBunVersion = () => result
  return result
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const testClient = <T extends Hono<any, Schema, string>>(
  app: T,
  Env?: ExtractEnv<T>['Bindings'] | {},
  executionCtx?: ExecutionContext,
  options?: Omit<ClientRequestOptions, 'fetch'>
): UnionToIntersection<Client<T, 'http://localhost'>> => {
  const customFetch = (input: RequestInfo | URL, init?: RequestInit) => {
    return app.request(input, init, Env, executionCtx)
  }

  return hc<typeof app, 'http://localhost'>('http://localhost', { ...options, fetch: customFetch })
}

/**
 * WebSocket Event Listeners type
 */
export interface WSEvents<T = unknown> {
  onOpen?: (evt: Event, ws: WSContext<T>) => void
  onMessage?: (evt: MessageEvent<WSMessageReceive>, ws: WSContext<T>) => void
  onClose?: (evt: CloseEvent, ws: WSContext<T>) => void
  onError?: (evt: Event, ws: WSContext<T>) => void
}

/**
 * Upgrade WebSocket Type
 */
export interface UpgradeWebSocket<T = unknown, U = any, _WSEvents = WSEvents<T>> {
  (
    createEvents: (c: Context) => _WSEvents | Promise<_WSEvents>,
    options?: U
  ): MiddlewareHandler<
    any,
    string,
    {
      outputFormat: 'ws'
    }
  >
  (
    c: Context,
    events: _WSEvents,
    options?: U
  ): Promise<Response & TypedResponse<{}, StatusCode, 'ws'>>
}

/**
 * Options for sending message
 */
export interface SendOptions {
  compress?: boolean
}

/**
 * A context for controlling WebSockets
 */
export class WSContext<T = unknown> {
  #init: WSContextInit<T>
  constructor(init: WSContextInit<T>) {
    this.#init = init
    this.raw = init.raw
    this.url = init.url ? new URL(init.url) : null
    this.protocol = init.protocol ?? null
  }
  send(source: string | ArrayBuffer | Uint8Array<ArrayBuffer>, options?: SendOptions): void {
    this.#init.send(source, options ?? {})
  }
  raw?: T
  binaryType: BinaryType = 'arraybuffer'
  get readyState(): WSReadyState {
    return this.#init.readyState
  }
  url: URL | null
  protocol: string | null
  close(code?: number, reason?: string) {
    this.#init.close(code, reason)
  }
}

export const createWSMessageEvent = (source: WSMessageReceive): MessageEvent<WSMessageReceive> => {
  return new MessageEvent<WSMessageReceive>('message', {
    data: source,
  })
}

export interface WebSocketHelperDefineContext {}
export type WebSocketHelperDefineHandler<T, U> = (
  c: Context,
  events: WSEvents<T>,
  options?: U
) => Promise<Response | void> | Response | void

/**
 * Create a WebSocket adapter/helper
 */
export const defineWebSocketHelper = <T = unknown, U = any>(
  handler: WebSocketHelperDefineHandler<T, U>
): UpgradeWebSocket<T, U> => {
  return ((
    ...args:
      | [createEvents: (c: Context) => WSEvents<T> | Promise<WSEvents<T>>, options?: U]
      | [c: Context, events: WSEvents<T>, options?: U]
  ) => {
    if (typeof args[0] === 'function') {
      const [createEvents, options] = args
      return async function upgradeWebSocket(c, next) {
        const events = await createEvents(c)
        const result = await handler(c, events, options as U)
        if (result) {
          return result
        }
        await next()
      }
    } else {
      const [c, events, options] = args as [c: Context, events: WSEvents<T>, options?: U]
      return (async () => {
        const upgraded = await handler(c, events, options as U)
        if (!upgraded) {
          throw new Error('Failed to upgrade WebSocket')
        }
        return upgraded
      })()
    }
  }) as UpgradeWebSocket<T, U>
}

const notFoundHandler: NotFoundHandler = (c) => {
  return c.text('404 Not Found', 404)
}

const errorHandler: ErrorHandler = (err, c) => {
  if ('getResponse' in err) {
    const res = err.getResponse()
    return c.newResponse(res.body, res)
  }
  console.error(err)
  return c.text('Internal Server Error', 500)
}

constructor(options: HonoOptions<E> = {}) {
  // Implementation of app.get(...handlers[]) or app.get(path, ...handlers[])
  const allMethods = [...METHODS, METHOD_NAME_ALL_LOWERCASE]
  allMethods.forEach((method) => {
    this[method] = (args1: string | H, ...args: H[]) => {
      const methodName = method.toUpperCase()
      if (typeof args1 === 'string') {
        this.#path = args1
      } else {
        this.#addRoute(methodName, this.#path, args1)
      }
      args.forEach((handler) => {
        this.#addRoute(methodName, this.#path, handler)
      })
      return this as any
    }
  })

  // Implementation of app.on(method, path, ...handlers[])
  this.on = (method: string | string[], path: string | string[], ...handlers: H[]) => {
    for (const p of [path].flat()) {
      this.#path = p
      for (const m of [method].flat()) {
        const methodName = m.toUpperCase()
        for (const handler of handlers) {
          this.#addRoute(methodName, this.#path, handler)
        }
      }
    }
    return this as any
  }

  // Implementation of app.use(...handlers[]) or app.use(path, ...handlers[])
  this.use = (arg1: string | MiddlewareHandler<any>, ...handlers: MiddlewareHandler<any>[]) => {
    if (typeof arg1 === 'string') {
      this.#path = arg1
    } else {
      this.#path = '*'
      handlers.unshift(arg1)
    }
    handlers.forEach((handler) => {
      this.#addRoute(METHOD_NAME_ALL, this.#path, handler)
    })
    return this as any
  }

  const { strict, ...optionsWithoutStrict } = options
  Object.assign(this, optionsWithoutStrict)
  this.getPath = (strict ?? true) ? (options.getPath ?? getPath) : getPathNoStrict
}

#clone(): Hono<E, S, BasePath, CurrentPath> {
  const clone = new Hono<E, S, BasePath, CurrentPath>({
    router: this.router,
    getPath: this.getPath,
  })
  clone.errorHandler = this.errorHandler
  clone.#notFoundHandler = this.#notFoundHandler
  clone.routes = this.routes
  return clone
}

/**
 * `.basePath()` allows base paths to be specified.
 *
 * @see {@link https://hono.dev/docs/api/routing#base-path}
 *
 * @param {string} path - base Path
 * @returns {Hono} changed Hono instance
 *
 * @example
 * ```ts
 * const api = new Hono().basePath('/api')
 * ```
 */
basePath<SubPath extends string>(
  path: SubPath
): Hono<E, S, MergePath<BasePath, SubPath>, MergePath<BasePath, SubPath>> {
  const subApp = this.#clone()
  subApp._basePath = mergePath(this._basePath, path)
  return subApp
}

/**
 * `.mount()` allows you to mount applications built with other frameworks into your Hono application.
 *
 * @see {@link https://hono.dev/docs/api/hono#mount}
 *
 * @param {string} path - base Path
 * @param {Function} applicationHandler - other Request Handler
 * @param {MountOptions} [options] - options of `.mount()`
 * @returns {Hono} mounted Hono instance
 *
 * @example
 * ```ts
 * import { Router as IttyRouter } from 'itty-router'
 * import { Hono } from 'hono'
 * // Create itty-router application
 * const ittyRouter = IttyRouter()
 * // GET /itty-router/hello
 * ittyRouter.get('/hello', () => new Response('Hello from itty-router'))
 *
 * const app = new Hono()
 * app.mount('/itty-router', ittyRouter.handle)
 * ```
 *
 * @example
 * ```ts
 * const app = new Hono()
 * // Send the request to another application without modification.
 * app.mount('/app', anotherApp, {
 *   replaceRequest: (req) => req,
 * })
 * ```
 */
mount(
  path: string,
  applicationHandler: (request: Request, ...args: any) => Response | Promise<Response>,
  options?: MountOptions
): Hono<E, S, BasePath, CurrentPath> {
  // handle options
  let replaceRequest: MountReplaceRequest | undefined
  let optionHandler: MountOptionHandler | undefined
  if (options) {
    if (typeof options === 'function') {
      optionHandler = options
    } else {
      optionHandler = options.optionHandler
      if (options.replaceRequest === false) {
        replaceRequest = (request) => request
      } else {
        replaceRequest = options.replaceRequest
      }
    }
  }

  // prepare handlers for request
  const getOptions: (c: Context) => unknown[] = optionHandler
    ? (c) => {
        const options = optionHandler!(c)
        return Array.isArray(options) ? options : [options]
      }
    : (c) => {

    }
  }

  // prepare handlers for request
  const getOptions: (c: Context) => unknown[] = optionHandler
    ? (c) => {
        const options = optionHandler!(c)
        return Array.isArray(options) ? options : [options]
      }
    : (c) => {
        let executionContext: ExecutionContext | undefined = undefined
        try {
          executionContext = c.executionCtx
        } catch {} // Do nothing
        return [c.env, executionContext]
      }
  replaceRequest ||= (() => {
    const mergedPath = mergePath(this._basePath, path)
    const pathPrefixLength = mergedPath === '/' ? 0 : mergedPath.length
    return (request) => {
      const url = new URL(request.url)
      url.pathname = this.getPath(request).slice(pathPrefixLength) || '/'
      return new Request(url, request)
    }
  })()

  const handler: MiddlewareHandler = async (c, next) => {
    const res = await applicationHandler(replaceRequest(c.req.raw), ...getOptions(c))

    if (res) {
      return res
    }

    await next()
  }
  this.#addRoute(METHOD_NAME_ALL, mergePath(path, '*'), handler)
  return this
}

#addRoute(method: string, path: string, handler: H, baseRoutePath?: string): void {
  path = mergePath(this._basePath, path)
  const r: RouterRoute = {
    basePath:
      baseRoutePath !== undefined ? mergePath(this._basePath, baseRoutePath) : this._basePath,
    path,
    method,
    handler,
  }
  this.router.add(method, path, [handler, r])
  this.routes.push(r)
}

#handleError(err: unknown, c: Context<E>): Response | Promise<Response> {
  if (err instanceof Error) {
    return this.errorHandler(err, c)
  }
  throw err
}

#dispatch(
  request: Request,
  executionCtx: ExecutionContext | FetchEventLike | undefined,
  env: E['Bindings'],
  method: string
): Response | Promise<Response> {
  // Handle HEAD method
  if (method === 'HEAD') {
    return (async () =>
      new Response(null, await this.#dispatch(request, executionCtx, env, 'GET')))()
  }

  const path = this.getPath(request, { env })
  const matchResult = this.router.match(method, path)

  const c = new Context(request, {
    path,
    matchResult,
    env,
    executionCtx,
    notFoundHandler: this.#notFoundHandler,
  })

  // Do not `compose` if it has only one handler
  if (matchResult[0].length === 1) {
    let res: ReturnType<H>
    try {
      res = matchResult[0][0][0][0](c, async () => {
        c.res = await this.#notFoundHandler(c)
      })
    } catch (err) {
      return this.#handleError(err, c)
    }

    return res instanceof Promise
      ? res
          .then(
            (resolved: Response | undefined) =>
              resolved || (c.finalized ? c.res : this.#notFoundHandler(c))
          )
          .catch((err: Error) => this.#handleError(err, c))
      : (res ?? this.#notFoundHandler(c))
  }

  const composed = compose(matchResult[0], this.errorHandler, this.#notFoundHandler)

  return (async () => {
    try {
      const context = await composed(c)
      if (!context.finalized) {
        throw new Error(
          'Context is not finalized. Did you forget to return a Response object or `await next()`?'
        )
      }

      return context.res
    } catch (err) {
      return this.#handleError(err, c)
    }
  })()
}

/**
 * `.fetch()` will be entry point of your app.
 *
 * @see {@link https://hono.dev/docs/api/hono#fetch}
 *
 * @param {Request} request - request Object of request
 * @param {Env} env - env Object
 * @param {ExecutionContext} executionCtx - context of execution
 * @returns {Response | Promise<Response>} response of request
 *
 */
fetch: (
  request: Request,
  env?: E['Bindings'] | {},
  executionCtx?: ExecutionContext
) => Response | Promise<Response> = (request, ...rest) => {
  return this.#dispatch(request, rest[1], rest[0], request.method)
}

/**
 * `.request()` is a useful method for testing.
 * You can pass a URL or pathname to send a GET request.
 * app will return a Response object.
 * ```ts
 * test('GET /hello is ok', async () => {
 *   const res = await app.request('/hello')
 *   expect(res.status).toBe(200)
 * })
 * ```
 * @see https://hono.dev/docs/api/hono#request
 */
request = (
  input: Request | string | URL,
  requestInit?: RequestInit,
  Env?: E['Bindings'] | {},
  executionCtx?: ExecutionContext
): Response | Promise<Response> => {
  if (input instanceof Request) {
    return this.fetch(requestInit ? new Request(input, requestInit) : input, Env, executionCtx)
  }
  input = input.toString()
  return this.fetch(
    new Request(
      /^https?:\/\//.test(input) ? input : `http://localhost${mergePath('/', input)}`,
      requestInit
    ),
    Env,
    executionCtx
  )
}

/**
 * `HTTPException` must be used when a fatal error such as authentication failure occurs.
 *
 * @see {@link https://hono.dev/docs/api/exception}
 *
 * @param {StatusCode} status - status code of HTTPException
 * @param {HTTPExceptionOptions} options - options of HTTPException
 * @param {HTTPExceptionOptions["res"]} options.res - response of options of HTTPException
 * @param {HTTPExceptionOptions["message"]} options.message - message of options of HTTPException
 * @param {HTTPExceptionOptions["cause"]} options.cause - cause of options of HTTPException
 *
 * @example
 * ```ts
 * import { HTTPException } from 'hono/http-exception'
 *
 * // ...
 *
 * app.post('/auth', async (c, next) => {
 *   // authentication
 *   if (authorized === false) {
 *     throw new HTTPException(401, { message: 'Custom error message' })
 *   }
 *   await next()
 * })
 * ```
 */
export class HTTPException extends Error {
  readonly res?: Response
  readonly status: ContentfulStatusCode

  /**
   * Creates an instance of `HTTPException`.
   * @param status - HTTP status code for the exception. Defaults to 500.
   * @param options - Additional options for the exception.
   */
  constructor(status: ContentfulStatusCode = 500, options?: HTTPExceptionOptions) {
    super(options?.message, { cause: options?.cause })
    this.res = options?.res
    this.status = status
  }

  /**
   * Returns the response object associated with the exception.
   * If a response object is not provided, a new response is created with the error message and status code.
   * @returns The response object.
   */
  getResponse(): Response {
    if (this.res) {
      const newResponse = new Response(this.res.body, {
        status: this.status,
        headers: this.res.headers,
      })
      return newResponse
    }
    return new Response(this.message, {
      status: this.status,
    })
  }
}

export type Element = HtmlEscapedString | Promise<HtmlEscapedString>
export type ElementType = string | ((props: never) => FunctionComponentResult)
export interface ElementChildrenAttribute {
  children: Child
}
export interface IntrinsicElements extends IntrinsicElementsDefined {
  [tagName: string]: Props
}
export interface IntrinsicAttributes {
  key?: string | number | bigint | null | undefined
}

const toSVGAttributeName = (key: string): string =>
  /[A-Z]/.test(key) &&
  // Presentation attributes are findable in style object. "clip-path", "font-size", "stroke-width", etc.
  // Or other un-deprecated kebab-case attributes. "overline-position", "paint-order", "strikethrough-position", etc.
  key.match(
    /^(?:al|basel|clip(?:Path|Rule)$|co|do|fill|fl|fo|gl|let|lig|i|marker[EMS]|o|pai|pointe|sh|st[or]|text[^L]|tr|u|ve|w)/
  )
    ? key.replace(/([A-Z])/g, '-$1').toLowerCase()
    : key

const resolveFunctionComponentResult = (
  result: Promise<string | JSXNode | Child[]>,
  suspendedContext?: SuspendedContext
): Promise<string> =>
  result.then((resolved) => {
    if (
      typeof resolved !== 'string' &&
      !Array.isArray(resolved) &&
      !(resolved instanceof JSXNode)
    ) {
      return resolved
    }
    const children = Array.isArray(resolved) ? resolved : [resolved as Child]
    const render = () => {
      const buffer: StringBufferWithCallbacks = [''] as StringBufferWithCallbacks
      childrenToStringToBuffer(children, buffer)
      return buffer.length === 1
        ? raw(buffer[0], buffer.callbacks)
        : stringBufferToString(buffer, buffer.callbacks)
    }
    return suspendedContext ? suspendedContext(render) : runWithRenderContext(render)
  })

const childrenToStringToBuffer = (children: Child[], buffer: StringBufferWithCallbacks): void => {
  for (let i = 0, len = children.length; i < len; i++) {
    const child = children[i]
    if (typeof child === 'string') {
      escapeToBuffer(child, buffer)
    } else if (typeof child === 'boolean' || child === null || child === undefined) {
      continue
    } else if (child instanceof JSXNode) {
      child.toStringToBuffer(buffer)
    } else if (typeof child === 'number') {
      ;(buffer[0] as string) += child
    } else if ((child as unknown as HtmlEscaped).isEscaped) {
      ;(buffer[0] as string) += child
      const callbacks = (child as unknown as HtmlEscapedString).callbacks
      if (callbacks) {
        buffer.callbacks ||= []
        buffer.callbacks.push(...callbacks)
      }
    } else if (child instanceof Promise) {
      buffer.unshift('', child)
    } else {
      // `child` type is `Child[]`, so stringify recursively
      childrenToStringToBuffer(child, buffer)
    }
  }
}

export const renderUntrustedObject = (
  value: unknown
): HtmlEscapedString | Promise<HtmlEscapedString> => {
  const stringified = (value as { toString(): unknown }).toString()
  const escape = (result: unknown) => renderChildren([String(result)])
  return stringified instanceof Promise ? stringified.then(escape) : escape(stringified)
}

constructor(tag: string | Function, props: Props, children: Child[]) {
  if (typeof tag !== 'function' && !isValidTagName(tag)) {
    throw new Error(`Invalid JSX tag name: ${tag}`)
  }
  this.tag = tag
  this.props = props
  this.children = children
}

get type(): string | Function {
  return this.tag as string
}

// Added for compatibility with libraries that rely on React's internal structure
// eslint-disable-next-line @typescript-eslint/no-explicit-any
get ref(): any {
  return this.props.ref || null
}

toString(): string | Promise<string> {
  const render = () => {
    const buffer: StringBufferWithCallbacks = [''] as StringBufferWithCallbacks
    this.toStringToBuffer(buffer)
    return buffer.length === 1
      ? 'callbacks' in buffer
        ? resolveCallbackSync(raw(buffer[0], buffer.callbacks)).toString()
        : buffer[0]
      : stringBufferToString(buffer, buffer.callbacks)
  }
  return runWithRenderContext(render)
}

toStringToBuffer(buffer: StringBufferWithCallbacks): void {
  const tag = this.tag as string
  const props = this.props
  let { children } = this

  buffer[0] += `<${tag}`

  const normalizeKey: (key: string) => string =
    tag === 'svg' || (nameSpaceContext && useContext(nameSpaceContext) === 'svg')
      ? (key) => toSVGAttributeName(normalizeIntrinsicElementKey(key))
      : (key) => normalizeIntrinsicElementKey(key)
  for (let [key, v] of Object.entries(props)) {
    key = normalizeKey(key)
    if (!isValidAttributeName(key)) {
      continue
    }
    if (key === 'children') {
      // skip children
    } else if (key === 'style' && typeof v === 'object') {
      // object to style strings
      let styleStr = ''
      styleObjectForEach(v, (property, value) => {
        if (value != null) {
          styleStr += `${styleStr ? ';' : ''}${property}:${value}`
        }
      })
      buffer[0] += ' style="'
      escapeToBuffer(styleStr, buffer)
      buffer[0] += '"'
    } else if (typeof v === 'string') {
      buffer[0] += ` ${key}="`
      escapeToBuffer(v, buffer)
      buffer[0] += '"'
    } else if (v === null || v === undefined) {
      // Do nothing
    } else if (typeof v === 'number' || (v as HtmlEscaped).isEscaped) {
      buffer[0] += ` ${key}="${v}"`
    } else if (typeof v === 'boolean' && booleanAttributes.includes(key)) {
      if (v) {
        buffer[0] += ` ${key}=""`
      }
    } else if (key === 'dangerouslySetInnerHTML') {
      if (children.length > 0) {
        throw new Error('Can only set one of `children` or `props.dangerouslySetInnerHTML`.')
      }

      children = [raw(v.__html)]
    } else if (v instanceof Promise) {
      buffer[0] += ` ${key}="`
      buffer.unshift('"', v)
    } else if (typeof v === 'function') {
      if (!key.startsWith('on') && key !== 'ref') {
        throw new Error(`Invalid prop '${key}' of type 'function' supplied to '${tag}'.`)
      }
      // maybe event handler for client components, just ignore in server components
    } else {
      buffer[0] += ` ${key}="`
      escapeToBuffer(v.toString(), buffer)
      buffer[0] += '"'
    }
  }

  if (emptyTags.includes(tag as string) && children.length === 0) {
    buffer[0] += '/>'
    return
  }

  buffer[0] += '>'

  childrenToStringToBuffer(children, buffer)

  buffer[0] += `</${tag}>`
}

class JSXFunctionNode extends JSXNode {
  override toStringToBuffer(buffer: StringBufferWithCallbacks): void {
    const { children } = this

    const props = { ...this.props }
    if (children.length) {
      props.children = children.length === 1 ? children[0] : children
    }

    const res = (this.tag as Function).call(null, props)

    if (typeof res === 'boolean' || res == null) {
      // boolean or null or undefined
      return
    } else if (res instanceof Promise) {
      if (globalContexts.length === 0) {
        buffer.unshift('', resolveFunctionComponentResult(res))
      } else {
        // save the current context state for resuming the suspended subtree
        buffer.unshift('', resolveFunctionComponentResult(res, captureRenderContext()))
      }
    } else if (res instanceof JSXNode) {
      res.toStringToBuffer(buffer)
    } else if (Array.isArray(res)) {
      childrenToStringToBuffer(res, buffer)
    } else if (typeof res === 'number' || (res as HtmlEscaped).isEscaped) {
      buffer[0] += res
      if (res.callbacks) {
        buffer.callbacks ||= []
        buffer.callbacks.push(...res.callbacks)
      }
    } else {
      escapeToBuffer(res, buffer)
    }
  }
}

export class JSXFragmentNode extends JSXNode {
  override toStringToBuffer(buffer: StringBufferWithCallbacks): void {
    childrenToStringToBuffer(this.children, buffer)
  }
}

export const jsx = (tag: string | Function, props: Props | null, ...children: Child[]): JSXNode => {
  props ??= {}
  if (children.length) {
    props.children = children.length === 1 ? children[0] : children
  }

  const key = props.key
  delete props['key']

  const node = jsxFn(tag, props, children)
  node.key = key
  return node
}

export const jsxFn = (tag: string | Function, props: Props, children: Child[]): JSXNode => {
  if (!initDomRenderer) {
    for (const k in domRenderers) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      ;(intrinsicElementTags[k as keyof typeof intrinsicElementTags] as any)[DOM_RENDERER] =
        domRenderers[k]
    }
    initDomRenderer = true
  }

  if (typeof tag === 'function') {
    return new JSXFunctionNode(tag, props, children)
  } else if (intrinsicElementTags[tag as keyof typeof intrinsicElementTags]) {
    return new JSXFunctionNode(
      intrinsicElementTags[tag as keyof typeof intrinsicElementTags],
      props,
      children
    )
  } else if (tag === 'svg' || tag === 'head') {
    nameSpaceContext ||= createContext('')
    return new JSXNode(tag, props, [
      new JSXFunctionNode(
        nameSpaceContext,
        {
          value: tag,
        },
        children
      ),
    ])
  } else {
    return new JSXNode(tag, props, children)
  }
}

export const shallowEqual = (a: Props, b: Props): boolean => {
  if (a === b) {
    return true
  }

  const aKeys = Object.keys(a).sort()
  const bKeys = Object.keys(b).sort()
  if (aKeys.length !== bKeys.length) {
    return false
  }

  for (let i = 0, len = aKeys.length; i < len; i++) {
    if (
      aKeys[i] === 'children' &&
      bKeys[i] === 'children' &&
      !a.children?.length &&
      !b.children?.length
    ) {
      continue
    } else if (a[aKeys[i]] !== b[aKeys[i]]) {
      return false
    }
  }

  return true
}

export type MemorableFC<T> = FC<T> & {
  [DOM_MEMO]: (prevProps: Readonly<T>, nextProps: Readonly<T>) => boolean
}

export const memo = <T>(
  component: FC<T>,
  propsAreEqual: (prevProps: Readonly<T>, nextProps: Readonly<T>) => boolean = shallowEqual
): FC<T> => {
  const wrapper: MemorableFC<T> = ((props: T) => component(props)) as MemorableFC<T>

  // This function is for toString(), but it can also be used for DOM renderer.
  // So, set DOM_MEMO and DOM_RENDERER for DOM renderer.
  wrapper[DOM_MEMO] = propsAreEqual
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  ;(wrapper as any)[DOM_RENDERER] = component

  return wrapper as FC<T>
}

export const Fragment = ({
  children,
}: {
  key?: string
  children?: Child | HtmlEscapedString
}): HtmlEscapedString => {
  return new JSXFragmentNode(
    '',
    {
      children,
    },
    Array.isArray(children) ? children : children ? [children] : []
  ) as never
}

export const isValidElement = (element: unknown): element is JSXNode => {
  return !!(element && typeof element === 'object' && 'tag' in element && 'props' in element)
}

export const cloneElement = <T extends JSXNode | JSX.Element>(
  element: T,
  props: Partial<Props>,
  ...children: Child[]
): T => {
  let childrenToClone
  if (children.length > 0) {
    childrenToClone = children
  } else {
    const c = (element as JSXNode).props.children
    childrenToClone = Array.isArray(c) ? c : [c]
  }
  return jsx(
    (element as JSXNode).tag,
    { ...(element as JSXNode).props, ...props },
    ...childrenToClone
  ) as T
}

export const Children = {
  map: (children: Child[], fn: (child: Child, index: number) => Child): Child[] =>
    toArray(children).map(fn),
  forEach: (children: Child[], fn: (child: Child, index: number) => void): void => {
    toArray(children).forEach(fn)
  },
  count: (children: Child[]): number => toArray(children).length,
  only: (_children: Child[]): Child => {
    const children = toArray(_children)
    if (children.length !== 1) {
      throw new Error('Children.only() expects only one child')
    }
    return children[0]
  },
  toArray,
}

export const childrenToString = async (children: Child[]): Promise<HtmlEscapedString[]> => {
  try {
    return children.flat().map(resolveChildEarly) as HtmlEscapedString[]
  } catch (e) {
    if (e instanceof Promise) {
      // Capture before `await`: on the fallback path the render context is
      // only observable during this synchronous window.
      const resume = captureRenderContext()
      await e
      return resume(() => childrenToString(children))
    } else {
      throw e
    }
  }
}

const resolveChildEarly = (child: Child): HtmlEscapedString | Promise<HtmlEscapedString> => {
  if (child == null || typeof child === 'boolean') {
    return '' as HtmlEscapedString
  } else if (typeof child === 'string' || Array.isArray(child)) {
    return renderChildren([child])
  } else if (isUntrustedObject(child)) {
    return renderUntrustedObject(child)
  } else {
    const str = child.toString()
    return str instanceof Promise ? (str as Promise<HtmlEscapedString>) : raw(str)
  }
}

/**
 * @experimental
 * `ErrorBoundary` is an experimental feature.
 * The API might be changed.
 */
export const ErrorBoundary: FC<
  PropsWithChildren<{
    fallback?: Child
    fallbackRender?: FallbackRender
    onError?: ErrorHandler
