  const resolveFallbackStr = (): Promise<HtmlEscapedString | string | undefined> =>
    (fallbackStrPromise ||= (async () => {
      const awaitedFallback = await fallback
      if (awaitedFallback === null || awaitedFallback === undefined) {
        return
