      if (typeof awaitedFallback === 'string' || Array.isArray(awaitedFallback)) {
        return getResume()(() => renderChildren([awaitedFallback]))
      }
      if (isUntrustedObject(awaitedFallback)) {
        return getResume()(() => renderUntrustedObject(awaitedFallback))
