const shouldTransform = (res: Response) => {
  const cacheControl = res.headers.get('Cache-Control')
  // Don't compress for Cache-Control: no-transform
  // https://tools.ietf.org/html/rfc7234#section-5.2.2.4
  return !cacheControl || !cacheControlNoTransformRegExp.test(cacheControl)
}

/**
 * Context Storage Middleware for Hono.
 *
 * @see {@link https://hono.dev/docs/middleware/builtin/context-storage}
 *
 * @returns {MiddlewareHandler} The middleware handler function.
 *
 * @example
 * ```ts
 * type Env = {
 *   Variables: {
 *     message: string
 *   }
 * }
 *
 * const app = new Hono<Env>()
 *
 * app.use(contextStorage())
 *
 * app.use(async (c, next) => {
 *   c.set('message', 'Hono is hot!!')
 *   await next()
 * })
 *
 * app.get('/', async (c) => c.text(getMessage()))
 *
 * const getMessage = () => {
 *   return getContext<Env>().var.message
 * }
 * ```
 */
export const contextStorage = (): MiddlewareHandler => {
  return async function contextStorage(c, next) {
    await asyncLocalStorage.run(c, next)
  }
}

export const tryGetContext = <E extends Env = Env>(): Context<E> | undefined => {
  return asyncLocalStorage.getStore() as Context<E> | undefined
}

export const getContext = <E extends Env = Env>(): Context<E> => {
  const context = tryGetContext<E>()
  if (!context) {
    throw new Error('Context is not available')
  }
  return context
}

const findAllowOrigin = ((optsOrigin) => {
  if (typeof optsOrigin === 'string') {
    if (optsOrigin === '*') {
      return () => optsOrigin
    } else {
      return (origin: string) => (optsOrigin === origin ? origin : null)
    }
  } else if (typeof optsOrigin === 'function') {
    return optsOrigin
  } else {
    return (origin: string) => (optsOrigin.includes(origin) ? origin : null)
  }
})(opts.origin)

const findAllowMethods = ((optsAllowMethods) => {
  if (typeof optsAllowMethods === 'function') {
    return async (origin: string, c: Context) => (await optsAllowMethods(origin, c)).join(',')
  } else if (Array.isArray(optsAllowMethods)) {
    const methodsStr = optsAllowMethods.join(',')
    return () => methodsStr
  } else {
    return () => ''
  }
})(opts.allowMethods)

return async function cors(c, next) {
  function set(key: string, value: string) {
    c.res.headers.set(key, value)
  }

  const allowOrigin = await findAllowOrigin(c.req.header('origin') || '', c)
  if (allowOrigin) {
    set('Access-Control-Allow-Origin', allowOrigin)
  }

  if (opts.credentials) {
    set('Access-Control-Allow-Credentials', 'true')
  }

  if (exposeHeadersStr) {
    set('Access-Control-Expose-Headers', exposeHeadersStr)
  }

  if (c.req.method === 'OPTIONS') {
    if (opts.origin !== '*') {
      c.res.headers.append('Vary', 'Origin')
    }

    if (opts.maxAge != null) {
      set('Access-Control-Max-Age', opts.maxAge.toString())
    }

    const allowMethods = await findAllowMethods(c.req.header('origin') || '', c)
    if (allowMethods) {
      set('Access-Control-Allow-Methods', allowMethods)
    }

    let headersStr = allowHeadersStr
    if (!headersStr) {

        set('Access-Control-Max-Age', opts.maxAge.toString())
      }

      const allowMethods = await findAllowMethods(c.req.header('origin') || '', c)
      if (allowMethods) {
        set('Access-Control-Allow-Methods', allowMethods)
      }

      let headersStr = allowHeadersStr
      if (!headersStr) {
        const requestHeaders = c.req.header('Access-Control-Request-Headers')
        if (requestHeaders) {
          headersStr = requestHeaders
            .split(',')
            .map((h) => h.trim())
            .join(',')
        }
      }
      if (headersStr) {
        set('Access-Control-Allow-Headers', headersStr)
        c.res.headers.append('Vary', 'Access-Control-Request-Headers')
      }

      c.res.headers.delete('Content-Length')
      c.res.headers.delete('Content-Type')

      return new Response(null, {
        headers: c.res.headers,
        status: 204,
        statusText: 'No Content',
      })
    }
    await next()

    // Suppose the server sends a response with an Access-Control-Allow-Origin value with an explicit origin (rather than the "*" wildcard).
    // https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Access-Control-Allow-Origin
    if (opts.origin !== '*') {
      c.header('Vary', 'Origin', { append: true })
    }
  }
}

type IsAllowedSecFetchSiteHandler = (
  secFetchSite: SecFetchSite,
  context: Context
) => boolean | Promise<boolean>

interface CSRFOptions {
  origin?: string | string[] | IsAllowedOriginHandler
  secFetchSite?: SecFetchSite | SecFetchSite[] | IsAllowedSecFetchSiteHandler
}

 *
 * // Dynamic origin validation
 * app.use('*', csrf({
 *   origin: (origin, c) => {
 *     // Allow same origin
 *     if (origin === new URL(c.req.url).origin) return true
 *     // Allow specific trusted domains
 *     return ['https://app.example.com', 'https://admin.example.com'].includes(origin)
 *   }
 * }))
 * ```
 */
export const csrf = (options?: CSRFOptions): MiddlewareHandler => {
  const originHandler: IsAllowedOriginHandler = ((optsOrigin) => {
    if (!optsOrigin) {
      return (origin, c) => origin === new URL(c.req.url).origin
    } else if (typeof optsOrigin === 'string') {
      return (origin) => origin === optsOrigin
    } else if (typeof optsOrigin === 'function') {
      return optsOrigin
    } else {
      return (origin) => optsOrigin.includes(origin)
    }
  })(options?.origin)
  const isAllowedOrigin = async (origin: string | undefined, c: Context) => {
    if (origin === undefined) {
      // denied always when origin header is not present
      return false
    }
    return await originHandler(origin, c)
  }

  const secFetchSiteHandler: IsAllowedSecFetchSiteHandler = ((optsSecFetchSite) => {
    if (!optsSecFetchSite) {
      // Default: only allow same-origin
      return (secFetchSite) => secFetchSite === 'same-origin'
    } else if (typeof optsSecFetchSite === 'string') {
      return (secFetchSite) => secFetchSite === optsSecFetchSite
    } else if (typeof optsSecFetchSite === 'function') {
      return optsSecFetchSite
    } else {
      return (secFetchSite) => optsSecFetchSite.includes(secFetchSite)
    }
  })(options?.secFetchSite)
  const isAllowedSecFetchSite = async (secFetchSite: string | undefined, c: Context) => {
    if (secFetchSite === undefined) {
      // denied always when sec-fetch-site header is not present
      return false
    }
    // type guard to check if the value is a valid SecFetchSite
    if (!isSecFetchSite(secFetchSite)) {
      return false
    }
    return await secFetchSiteHandler(secFetchSite, c)
  }

  return async function csrf(c, next) {
    if (
      !isSafeMethodRe.test(c.req.method) &&
      isRequestedByFormElementRe.test(c.req.header('content-type') || 'text/plain') &&

    if (!isSecFetchSite(secFetchSite)) {
      return false
    }
    return await secFetchSiteHandler(secFetchSite, c)
  }

  return async function csrf(c, next) {
    if (
      !isSafeMethodRe.test(c.req.method) &&
      isRequestedByFormElementRe.test(c.req.header('content-type') || 'text/plain') &&
      !(await isAllowedSecFetchSite(c.req.header('sec-fetch-site'), c)) &&
      !(await isAllowedOrigin(c.req.header('origin'), c))
    ) {
      const res = new Response('Forbidden', { status: 403 })
      throw new HTTPException(403, { res })
    }

    await next()
  }
}

const mergeBuffers = (
  buffer1: ArrayBuffer | undefined,
  buffer2: Uint8Array<ArrayBuffer>
): Uint8Array<ArrayBuffer> => {
  if (!buffer1) {
    return buffer2
  }
  const merged = new Uint8Array<ArrayBuffer>(
    new ArrayBuffer(buffer1.byteLength + buffer2.byteLength)
  )
  merged.set(new Uint8Array(buffer1), 0)
  merged.set(buffer2, buffer1.byteLength)
  return merged
}

export const generateDigest = async (
  stream: ReadableStream<Uint8Array<ArrayBuffer>> | null,
  generator: (body: Uint8Array<ArrayBuffer>) => ArrayBuffer | Promise<ArrayBuffer>
): Promise<string | null> => {
  if (!stream) {
    return null
  }

  let result: ArrayBuffer | undefined = undefined
  let chunk: Uint8Array<ArrayBuffer> | undefined
  let chunkLength = 0

  const digest = async (body: Uint8Array<ArrayBuffer>) => {
    result = await generator(mergeBuffers(result, body))
  }

  const reader = stream.getReader()
  for (;;) {
    const { value, done } = await reader.read()
    if (done) {
      break
    }

    let offset = 0
    while (offset < value.byteLength) {
      const remaining = value.byteLength - offset

      if (chunkLength === 0 && remaining >= CHUNK_SIZE) {
        await digest(value.subarray(offset, offset + CHUNK_SIZE))
        offset += CHUNK_SIZE
        continue
      }

      const requiredLength = chunkLength + remaining
      if (requiredLength < CHUNK_SIZE) {
        if (!chunk) {
          chunk = value.slice(offset)
        } else {
          if (chunk.byteLength < requiredLength) {
            const nextChunk = new Uint8Array<ArrayBuffer>(
              new ArrayBuffer(Math.min(CHUNK_SIZE, Math.max(requiredLength, chunk.byteLength * 2)))
            )
            nextChunk.set(chunk.subarray(0, chunkLength))
            chunk = nextChunk
          }
          chunk.set(value.subarray(offset), chunkLength)
        }
        chunkLength = requiredLength
        break
      }

      const length = CHUNK_SIZE - chunkLength
      if (chunk?.byteLength !== CHUNK_SIZE) {
        const nextChunk = new Uint8Array<ArrayBuffer>(new ArrayBuffer(CHUNK_SIZE))
        if (chunk) {
          nextChunk.set(chunk.subarray(0, chunkLength))
        }
        chunk = nextChunk
      }
      chunk.set(value.subarray(offset, offset + length), chunkLength)
      await digest(chunk)
      chunkLength = 0
      offset += length
    }
  }

  if (chunk && chunkLength > 0) {
    await digest(chunk.subarray(0, chunkLength))
  }

  if (!result) {
    return null
  }

  return Array.prototype.map
    .call(new Uint8Array(result), (x) => x.toString(16).padStart(2, '0'))
    .join('')
}

type ETagOptions = {
  retainedHeaders?: string[]
  weak?: boolean
  generateDigest?: (body: Uint8Array<ArrayBuffer>) => ArrayBuffer | Promise<ArrayBuffer>
}

function etagMatches(etag: string, ifNoneMatch: string | null) {
  return (
    ifNoneMatch != null &&
    ifNoneMatch.split(',').some((t) => stripWeak(t.trim()) === stripWeak(etag))
  )
}

function initializeGenerator(
  generator?: ETagOptions['generateDigest']
): ETagOptions['generateDigest'] | undefined {
  if (!generator) {
    if (crypto && crypto.subtle) {
      generator = (body: Uint8Array<ArrayBuffer>) =>
        crypto.subtle.digest(
          {
            name: 'SHA-1',
          },
          body
        )
    }
  }

  return generator
}

/**
 * ETag Middleware for Hono.
 *
 * @see {@link https://hono.dev/docs/middleware/builtin/etag}
 *
 * @param {ETagOptions} [options] - The options for the ETag middleware.
 * @param {boolean} [options.weak=false] - Define using or not using a weak validation. If true is set, then `W/` is added to the prefix of the value.
 * @param {string[]} [options.retainedHeaders=RETAINED_304_HEADERS] - The headers that you want to retain in the 304 Response.
 * @param {function(Uint8Array): ArrayBuffer | Promise<ArrayBuffer>} [options.generateDigest] -
 * A custom digest generation function. By default, it uses 'SHA-1'
 * This function is called with the response body as a `Uint8Array` and should return a hash as an `ArrayBuffer` or a Promise of one.
 * @returns {MiddlewareHandler} The middleware handler function.
 *
 * @example
 * ```ts
 * const app = new Hono()
 *
 * app.use('/etag/*', etag())
 * app.get('/etag/abc', (c) => {
 *   return c.text('Hono is hot')
 * })
 * ```
 */
export const etag = (options?: ETagOptions): MiddlewareHandler => {
  const retainedHeaders = options?.retainedHeaders ?? RETAINED_304_HEADERS
  const weak = options?.weak ?? false
  const generator = initializeGenerator(options?.generateDigest)

  return async function etag(c, next) {
    const ifNoneMatch = c.req.header('If-None-Match') ?? null

    await next()

    if (
      !(c.req.method === 'GET' || c.req.method === 'HEAD' || c.req.method === 'QUERY') ||
      !c.res.ok
    ) {
      return
    }

    const res = c.res as Response
    let etag = res.headers.get('ETag')

    if (!etag) {
      if (!generator) {
        return
      }
      const hash = await generateDigest(
        // This type casing avoids the type error for `deno publish`
        res.clone().body as ReadableStream<Uint8Array<ArrayBuffer>>,
        generator
      )
      if (hash === null) {
        return
      }
      etag = weak ? `W/"${hash}"` : `"${hash}"`
    }

    const matched = ifNoneMatch === '*' || etagMatches(etag, ifNoneMatch)

    if (matched) {
      c.res = new Response(null, {
        status: 304,
        statusText: 'Not Modified',
        headers: {
          ETag: etag,
        },
      })
      for (const key of Array.from(c.res.headers.keys())) {
        if (retainedHeaders.indexOf(key.toLowerCase()) === -1) {
          c.res.headers.delete(key)
        }
      }
    } else {
      c.res.headers.set('ETag', etag)
    }
  }
}

const parseCidrPrefix = (rule: string, prefix: string, max: number): number => {
  if (!/^[0-9]{1,3}$/.test(prefix)) {
    throw new TypeError(`Invalid rule: ${rule}`)
  }
  const parsedPrefix = parseInt(prefix)
  if (parsedPrefix > max) {
    throw new TypeError(`Invalid rule: ${rule}`)
  }
  return parsedPrefix
}

const buildMatcher = (
  rules: IPRestrictionRule[]
): ((addr: { addr: string; type: AddressType; isIPv4: boolean }) => boolean) => {
  const functionRules: IPRestrictionRuleFunction[] = []
  const staticRules: Set<string> = new Set()
  const staticIPv4Rules: Set<bigint> = new Set()
  const staticIPv6Rules: Set<bigint> = new Set()
  const cidrRules: [boolean, bigint, bigint][] = []
  const registerStaticRule = (rule: string): void => {
    const type = distinctRemoteAddr(rule)
    if (type === undefined) {
      throw new TypeError(`Invalid rule: ${rule}`)
    }
    if (type === 'IPv4') {
      const ipv4binary = convertIPv4ToBinary(rule)
      staticRules.add(rule)
      staticRules.add(`::ffff:${rule}`)
      staticIPv4Rules.add(ipv4binary)
      staticIPv6Rules.add((0xffffn << 32n) | ipv4binary)
    } else {
      const ipv6binary = convertIPv6ToBinary(rule)
      const ipv6Addr = convertIPv6BinaryToString(ipv6binary)
      staticRules.add(ipv6Addr)
      staticIPv6Rules.add(ipv6binary)
      if (isIPv4MappedIPv6(ipv6binary)) {
        staticRules.add(ipv6Addr.substring(7)) // remove ::ffff: prefix
        staticIPv4Rules.add(convertIPv4MappedIPv6ToIPv4(ipv6binary))
      }
    }
  }

  for (let rule of rules) {
    if (rule === '*') {
      return () => true
    } else if (typeof rule === 'function') {
      functionRules.push(rule)
    } else {
      if (IS_CIDR_NOTATION_REGEX.test(rule)) {
        const separatedRule = rule.split('/')

        const addrStr = separatedRule[0]
        const type = distinctRemoteAddr(addrStr)
        if (type === undefined) {
          throw new TypeError(`Invalid rule: ${rule}`)
        }

        let isIPv4 = type === 'IPv4'
        let prefix = parseCidrPrefix(rule, separatedRule[1], isIPv4 ? 32 : 128)

        if (isIPv4 ? prefix === 32 : prefix === 128) {
          // this rule is a static rule
          rule = addrStr
        } else {
          let addr = (isIPv4 ? convertIPv4ToBinary : convertIPv6ToBinary)(addrStr)
          if (type === 'IPv6' && isIPv4MappedIPv6(addr) && prefix >= 96) {
            isIPv4 = true
            addr = convertIPv4MappedIPv6ToIPv4(addr)
            prefix -= 96
          }

        // this rule is a static rule
        rule = addrStr
      } else {
        let addr = (isIPv4 ? convertIPv4ToBinary : convertIPv6ToBinary)(addrStr)
        if (type === 'IPv6' && isIPv4MappedIPv6(addr) && prefix >= 96) {
          isIPv4 = true
          addr = convertIPv4MappedIPv6ToIPv4(addr)
          prefix -= 96
        }

        const mask = ((1n << BigInt(prefix)) - 1n) << BigInt((isIPv4 ? 32 : 128) - prefix)

        cidrRules.push([isIPv4, addr & mask, mask] as [boolean, bigint, bigint])
        continue
      }
    }

    registerStaticRule(rule)
  }
}

return (remote: {
  addr: string
  type: AddressType
  isIPv4: boolean
  binaryAddr?: bigint
}): boolean => {
  if (staticRules.has(remote.addr)) {
    return true
  }
  const remoteAddr = (remote.binaryAddr ||= (
    remote.isIPv4 ? convertIPv4ToBinary : convertIPv6ToBinary
  )(remote.addr))
  const remoteIPv4Addr =
    remote.isIPv4 || isIPv4MappedIPv6(remoteAddr)
      ? remote.isIPv4
        ? remoteAddr
        : convertIPv4MappedIPv6ToIPv4(remoteAddr)
      : undefined
  if ((remote.isIPv4 ? staticIPv4Rules : staticIPv6Rules).has(remoteAddr)) {
    return true
  }
  for (const [isIPv4, addr, mask] of cidrRules) {
    if (isIPv4) {
      if (remoteIPv4Addr === undefined) {
        continue
      }
      if ((remoteIPv4Addr & mask) === addr) {
        return true
      }
      continue
    }
    if (remote.isIPv4) {
      continue
    }
    if ((remoteAddr & mask) === addr) {
      return true
    }
  }
  for (const rule of functionRules) {

        continue
      }
      if (remote.isIPv4) {
        continue
      }
      if ((remoteAddr & mask) === addr) {
        return true
      }
    }
    for (const rule of functionRules) {
      if (rule({ addr: remote.addr, type: remote.type })) {
        return true
      }
    }
    return false
  }
}

/**
 * Rules for IP Restriction Middleware
 */
export interface IPRestrictionRules {
  denyList?: IPRestrictionRule[]
  allowList?: IPRestrictionRule[]
}

  const denyMatcher = buildMatcher(denyList)
  const allowMatcher = buildMatcher(allowList)

  const blockError = (c: Context): HTTPException =>
    new HTTPException(403, {
      res: c.text('Forbidden', {
        status: 403,
      }),
    })

  return async function ipRestriction(c, next) {
    const connInfo = getIP(c)
    const addr = typeof connInfo === 'string' ? connInfo : connInfo.remote.address
    if (!addr) {
      throw blockError(c)
    }
    const type =
      (typeof connInfo !== 'string' && connInfo.remote.addressType) || distinctRemoteAddr(addr)

    const remoteData = { addr, type, isIPv4: type === 'IPv4' }

    try {
      if (denyMatcher(remoteData)) {
        if (onError) {
          return onError({ addr, type }, c)
        }
        throw blockError(c)
      }
      if (allowMatcher(remoteData)) {
        return await next()
      }
    } catch (e) {
      if (
        e instanceof TypeError &&
        (e as InvalidIPAddressError).code === INVALID_IP_ADDRESS_ERROR_CODE
      ) {
        // If an invalid IP address is specified, treat it as if no IP address was specified
        throw blockError(c)
      }
      throw e
    }

    if (allowLength === 0) {
      return await next()
    } else {
      if (onError) {
        return await onError({ addr, type }, c)
      }
      throw blockError(c)
    }
  }
}

type RendererOptions = {
  docType?: boolean | string
  stream?: boolean | Record<string, string>
}

type ComponentResult = Exclude<ReturnType<FC>, null>

type Component = (props: PropsForRenderer & { Layout: FC }, c: Context) => ComponentResult

type ComponentWithChildren = (
  props: PropsWithChildren<PropsForRenderer & { Layout: FC }>,
  c: Context
) => ComponentResult

const createRenderer =
  (
    c: Context,
    Layout: FC,
    component?: Component,
    options?: RendererOptions | ((c: Context) => RendererOptions)
  ) =>
  (children: JSXNode, props: PropsForRenderer) => {
    options = typeof options === 'function' ? options(c) : options
    const docType =
      typeof options?.docType === 'string'
        ? options.docType
        : options?.docType === false
          ? ''
          : '<!DOCTYPE html>'

    const currentLayout = component
      ? jsx(
          (props: any) => component(props, c),
          {
            Layout,
            ...(props as any),
          },
          children as any
        )
      : children

    const body = html`${raw(docType)}${jsx(
      RequestContext.Provider,
      { value: c },
      currentLayout as any
    )}`

    if (options?.stream) {
      if (options.stream === true) {
        c.header('Transfer-Encoding', 'chunked')
        c.header('Content-Type', 'text/html; charset=UTF-8')
        c.header('Content-Encoding', 'Identity')
      } else {
        for (const [key, value] of Object.entries(options.stream)) {
          c.header(key, value)
        }
      }
      return c.body(renderToReadableStream(body))
    } else {
      return c.html(body)
    }
  }

export const jwk = (
  options: {
    keys?: HonoJsonWebKey[] | ((ctx: Context) => Promise<HonoJsonWebKey[]> | HonoJsonWebKey[])
    jwks_uri?: string | ((ctx: Context) => Promise<string> | string)
    allow_anon?: boolean
    cookie?:
      | string
      | { key: string; secret?: string | BufferSource; prefixOptions?: CookiePrefixOptions }

    headerName?: string

    alg: AsymmetricAlgorithm[]

    realm?: string

    verification?: VerifyOptions
  },
  init?: RequestInit
): MiddlewareHandler => {
  const verifyOpts = options.verification || {}

  if (!options || !(options.keys || options.jwks_uri)) {
    throw new Error('JWK auth middleware requires options for either "keys" or "jwks_uri" or both')
  }

  if (!crypto.subtle || !crypto.subtle.importKey) {
    throw new Error('`crypto.subtle.importKey` is undefined. JWK auth middleware requires it.')
  }

  return async function jwk(ctx, next) {
    const headerName = options.headerName || 'Authorization'

    const credentials = ctx.req.raw.headers.get(headerName)
    let token
    if (credentials) {
      const parts = credentials.split(/\s+/)
      if (parts.length !== 2 || parts[0].toLowerCase() !== 'bearer') {
        const errDescription = 'invalid credentials structure'
        throw new HTTPException(401, {
          message: errDescription,
          res: unauthorizedResponse({
            ctx,
            error: 'invalid_request',
            errDescription,
            realm: options.realm,
          }),
        })
      } else {
        token = parts[1]
      }
    } else if (options.cookie) {
      if (typeof options.cookie == 'string') {
        token = getCookie(ctx, options.cookie)
      } else if (options.cookie.secret) {
        if (options.cookie.prefixOptions) {
          token = await getSignedCookie(
            ctx,
            options.cookie.secret,
            options.cookie.key,
            options.cookie.prefixOptions

} else if (options.cookie) {
  if (typeof options.cookie == 'string') {
    token = getCookie(ctx, options.cookie)
  } else if (options.cookie.secret) {
    if (options.cookie.prefixOptions) {
      token = await getSignedCookie(
        ctx,
        options.cookie.secret,
        options.cookie.key,
        options.cookie.prefixOptions
      )
    } else {
      token = await getSignedCookie(ctx, options.cookie.secret, options.cookie.key)
    }
  } else {
    if (options.cookie.prefixOptions) {
      token = getCookie(ctx, options.cookie.key, options.cookie.prefixOptions)
    } else {
      token = getCookie(ctx, options.cookie.key)
    }
  }
}

if (!token) {
  if (options.allow_anon) {
    return next()
  }
  const errDescription = 'no authorization included in request'
  throw new HTTPException(401, {
    message: errDescription,
    res: unauthorizedResponse({
      ctx,
      error: 'invalid_request',
      errDescription,
      realm: options.realm,
    }),
  })
}

let payload
let cause
try {
  const keys = typeof options.keys === 'function' ? await options.keys(ctx) : options.keys
  const jwks_uri =
    typeof options.jwks_uri === 'function' ? await options.jwks_uri(ctx) : options.jwks_uri
  payload = await Jwt.verifyWithJwks(
    token,
    { keys, jwks_uri, verification: verifyOpts, allowedAlgorithms: options.alg },
    init
  )
} catch (e) {
  cause = e
}

