    const pattern =
      token.length === 1
        ? token === '*'
          ? i === len - 1
            ? ['', '', ONLY_WILDCARD_REG_EXP_STR] // '*' matches to all the trailing paths
            : ['', '', LABEL_REG_EXP_STR]
          : null
