      nextNode = node.#children[regexpStr]
      if (!nextNode) {
        if (regexpStr !== ONLY_WILDCARD_REG_EXP_STR && regexpStr !== TAIL_WILDCARD_REG_EXP_STR) {
          for (const k in node.#children) {
            if (
              // a single-char pattern coexists with single-char literals as a literal does
              (regexpStr.length > 1 || k.length > 1) &&
              k !== ONLY_WILDCARD_REG_EXP_STR &&
              k !== TAIL_WILDCARD_REG_EXP_STR
            ) {
              throw PATH_ERROR
            }
          }
        }
        nextNode = node.#children[regexpStr] = new Node()
      }
      if (name !== '') {
        nextNode.#varIndex ??= context.varIndex++
        paramMap.push([name, nextNode.#varIndex])

            ) {
              throw PATH_ERROR
            }
          }
        }
        nextNode = node.#children[regexpStr] = new Node()
      }
      if (name !== '') {
        nextNode.#varIndex ??= context.varIndex++
        paramMap.push([name, nextNode.#varIndex])
      }
    } else {
      nextNode = node.#children[token]
      if (!nextNode) {
        for (const k in node.#children) {
          if (
            k.length > 1 &&
            k !== ONLY_WILDCARD_REG_EXP_STR &&
            k !== TAIL_WILDCARD_REG_EXP_STR
          ) {
            throw PATH_ERROR
          }
        }
        nextNode = node.#children[token] = new Node()
      }
    }

    node = nextNode
  }

  if (node.#index !== undefined) {
    throw PATH_ERROR
  }
  node.#index = isStatic ? -1 : index
}

buildRegExpStr(): string {
  const childKeys = Object.keys(this.#children).sort(compareKey)

  const strList = childKeys
    .map((k) => {
      const c = this.#children[k]
      const childStr = c.buildRegExpStr()
      // an empty childStr means a static-only branch, which is handled by staticMap
      return childStr === ''
        ? ''
        : (typeof c.#varIndex === 'number'
            ? `(${k})@${c.#varIndex}`
            : regExpMetaChars.has(k)
              ? `\\${k}`
              : k) + childStr
    })
    .filter(Boolean)

  if (typeof this.#index === 'number' && this.#index !== -1) {
    strList.unshift(`#${this.#index}`)
  }

  if (strList.length === 0) {
    return ''
  }
  if (strList.length === 1) {
    return strList[0]
  }

  return '(?:' + strList.join('|') + ')'
}

constructor(matchers: MatcherMap<T>, relocateMap: RelocateMap) {
  this.#matchers = matchers
  this.#relocateMap = relocateMap
}

#addWildcard(method: string, handlerData: [T, ParamIndexMap]) {
  const matcher = this.#matchers[method] as Matcher<T>
  matcher[1].forEach((list) => list && list.push(handlerData))
  Object.values(matcher[2]).forEach((list) => (list[0] as [T, ParamIndexMap][]).push(handlerData))
}

#addPath(
  method: string,
  path: string,
  handler: T,
  indexes: (number | string)[],
  map: ParamIndexMap | undefined
) {
  const matcher = this.#matchers[method] as Matcher<T>
  if (!map) {
    // assumed to be a static route
    matcher[2][path][0].push([handler, {}])
  } else {
    indexes.forEach((index) => {
      if (typeof index === 'number') {
        matcher[1][index].push([handler, map])
      } else {
        ;(matcher[2][index || path][0] as [T, ParamIndexMap][]).push([handler, map])
      }
    })
  }
}

add(method: string, path: string, handler: T) {
  if (!this.#matchers[method]) {
    const all = this.#matchers[METHOD_NAME_ALL] as Matcher<T>
    const staticMap = {} as StaticMap<T>
    for (const key in all[2]) {
      staticMap[key] = [all[2][key][0].slice(), emptyParam] as Result<T>
    }
    this.#matchers[method] = [
      all[0],
      all[1].map((list) => (Array.isArray(list) ? list.slice() : 0)) as HandlerData<T>[],
      staticMap,
    ]
  }

  if (path === '/*' || path === '*') {
    const handlerData: [T, ParamIndexMap] = [handler, {}]
    if (method === METHOD_NAME_ALL) {
      for (const m in this.#matchers) {
        this.#addWildcard(m, handlerData)
      }
    } else {
      this.#addWildcard(method, handlerData)
    }
    return
  }

  const data = this.#relocateMap[path]
  if (!data) {
    throw new Error(`Path ${path} is not registered`)
  }
  for (const [indexes, map] of data) {
    if (method === METHOD_NAME_ALL) {
      for (const m in this.#matchers) {
        this.#addPath(m, path, handler, indexes, map)
      }
    } else {
      this.#addPath(method, path, handler, indexes, map)
    }
  }
}

protected buildAllMatchers(): MatcherMap<T> {
  return this.#matchers
}

export const buildInitParams: (params: {
  paths: string[]
}) => ConstructorParameters<typeof PreparedRegExpRouter> = ({ paths }) => {
  const RegExpRouterWithMatcherExport = class<T> extends RegExpRouter<T> {
    buildAndExportAllMatchers() {
      return this.buildAllMatchers()
    }
  }
  const router = new RegExpRouterWithMatcherExport<string>()
  for (const path of paths) {
    router.add(METHOD_NAME_ALL, path, path)
  }

  const matchers = router.buildAndExportAllMatchers()
  const all = matchers[METHOD_NAME_ALL] as Matcher<string>

  const relocateMap: RelocateMap = {}
  for (const path of paths) {
    if (path === '/*' || path === '*') {
      continue
    }
    all[1].forEach((list, i) => {
      list.forEach(([p, map]) => {
        if (p === path) {
          if (relocateMap[path]) {
            relocateMap[path][0][1] = {
              ...relocateMap[path][0][1],
              ...map,
            }
          } else {
            relocateMap[path] = [[[], map]]
          }
          if (relocateMap[path][0][0].findIndex((j) => j === i) === -1) {
            relocateMap[path][0][0].push(i)
          }
        }
      })
    })
    for (const path2 in all[2]) {
      all[2][path2][0].forEach(([p]) => {
        if (p === path) {
          relocateMap[path] ||= [[[]]]
          const value = path2 === path ? '' : path2
          if (relocateMap[path][0][0].findIndex((v) => v === value) === -1) {
            relocateMap[path][0][0].push(value)
          }
        }
      })
    }
  }

  for (let i = 0, len = all[1].length; i < len; i++) {
    all[1][i] = all[1][i] ? [] : (0 as unknown as HandlerData<string>)
  }
  for (const path in all[2]) {
    all[2][path][0] = []
  }

  return [matchers, relocateMap]
}

export const serializeInitParams: (
  params: ConstructorParameters<typeof PreparedRegExpRouter>
) => string = ([matchers, relocateMap]) => {
  // Embed the regular expression as a result of `toString()` so that it can be evaluated as JavaScript.
  const matchersStr = JSON.stringify(matchers, (_, value) =>
    value instanceof RegExp ? `##${value.toString()}##` : value
  ).replace(/"##(.+?)##"/g, (_, str) => str.replace(/\\\\/g, '\\'))
  const relocateMapStr = JSON.stringify(relocateMap)
  return `[${matchersStr},${relocateMapStr}]`
}

function buildWildcardRegExp(path: string): RegExp {
  return (wildcardRegExpCache[path] ??= new RegExp(
    `^${path.replace(
      /\/:[^/{}]+(?:\{\[\^\/]\+})?(?=[/{]|$)|\/?\*$|([.\\+*[^\]$()?{}|])/g,
      (match, metaChar) =>
        metaChar
          ? `\\${metaChar}`
          : match === '/*'
            ? TAIL_WILDCARD_REG_EXP_STR
            : match === '*'
              ? ONLY_WILDCARD_REG_EXP_STR
              : `/:${LABEL_REG_EXP_STR}`
    )}$`
  ))
}

function findMiddleware<T>(middleware: Record<string, T[]>, path: string): T[] | undefined {
  for (const k of Object.keys(middleware).sort((a, b) => b.length - a.length)) {
    if (buildWildcardRegExp(k).test(path)) {
      return [...middleware[k]]
    }
  }

  return undefined
}

constructor() {
  this.#middleware = { [METHOD_NAME_ALL]: createNullObject() }
  this.#routes = { [METHOD_NAME_ALL]: createNullObject() }
  this.#tries = { [METHOD_NAME_ALL]: new Trie() }
}

#insertPath(method: string, path: string) {
  try {
    this.#tries![method].insert(path, !/\*|\/:/.test(path))
  } catch (e) {
    throw e === PATH_ERROR ? new UnsupportedPathError(path) : e
  }
}

add(method: string, path: string, handler: T) {
  const middleware = this.#middleware
  const routes = this.#routes!

  if (!middleware) {
    throw new Error(MESSAGE_MATCHER_IS_ALREADY_BUILT)
  }

  if (!middleware[method]) {
    this.#tries![method] = new Trie()
    for (const handlerMap of [middleware, routes]) {
      handlerMap[method] = createNullObject()
      for (const p in handlerMap[METHOD_NAME_ALL]) {
        handlerMap[method][p] = [...handlerMap[METHOD_NAME_ALL][p]]
        this.#insertPath(method, p)
      }
    }
  }

  if (path === '/*') {
    path = '*'
  }
  const methods = method === METHOD_NAME_ALL ? Object.keys(middleware) : [method]

  if (/\*$/.test(path)) {
    const re = buildWildcardRegExp(path)
    for (const m of methods) {
      if (!middleware[m][path]) {
        this.#insertPath(m, path)
        middleware[m][path] =
          findMiddleware(middleware[m], path) ||
          findMiddleware(middleware[METHOD_NAME_ALL], path) ||
          []
      }
    }
    for (const handlerMap of [middleware, routes]) {
      for (const m of methods) {
        for (const p in handlerMap[m]) {
          re.test(p) && handlerMap[m][p].push([handler, path])
        }
      }
    }

    return
  }

  const paths = checkOptionalParameter(path) || [path]
  for (const path of paths) {
    for (const m of methods) {
      if (!routes[m][path]) {
        this.#insertPath(m, path)
        routes[m][path] =
          findMiddleware(middleware[m], path) ||
          findMiddleware(middleware[METHOD_NAME_ALL], path) ||
          []
      }
      routes[m][path].push([handler, path])
    }
  }
}

protected buildAllMatchers(): MatcherMap<T> {
  const matchers: MatcherMap<T> = createNullObject()

  for (const method of Object.keys(this.#routes!)) {
    matchers[method] = this.#buildMatcher(method)
  }

  // Release cache
  this.#middleware = this.#routes = this.#tries = undefined
  wildcardRegExpCache = createNullObject()

  return matchers
}

#buildMatcher(method: string): Matcher<T> {
  const middleware = this.#middleware![method]
  const routes = this.#routes![method]

  const trie = this.#tries![method]
  const staticMap: StaticMap<T> = createNullObject()
  const handlerData: HandlerData<T>[] = []
  const [regexp, indexReplacementMap, paramReplacementMap] = trie.buildRegExp()

  for (const r of [middleware, routes]) {
    for (const path in r) {
      const handlers = r[path]
      const pathData = trie.paths[path]
      if (!pathData) {
        staticMap[path] = [handlers.map(([h]) => [h, createNullObject()]), emptyParam]
        continue
      }
      handlerData[pathData[0]] = handlers.map(([h, handlerPath]) => [
        h,
        trie.paths[handlerPath][1].reduceRight((map, [key], i) => {
          map[key] = paramReplacementMap[pathData[1][i][1]]
          return map
        }, createNullObject()),
      ])
    }
  }

  return [regexp, indexReplacementMap.map((i) => handlerData[i]), staticMap] as Matcher<T>
}

export class Trie {
  #context: Context = { varIndex: 0 }
  #root: Node = new Node()
  #index: number = 0
  // dynamic path -> [handler index, param assoc]; static paths are not registered
  paths: Record<string, [number, ParamAssocArray]> = createNullObject()

  insert(path: string, isStatic: boolean): void {
    if (isStatic) {
      // a static path has no pattern; every character is a literal token
      this.#root.insert(path.split(''), 0, [], this.#context, true)
      return
    }

    const paramAssoc: ParamAssocArray = []

    const groups: [string, string][] = [] // [mark, original string]
    let markedPath = path
    for (let i = 0; ; ) {
      let replaced = false
      markedPath = markedPath.replace(/\{[^}]+\}/g, (m) => {
        const mark = `@\\${i}`
        groups[i] = [mark, m]
        i++
        replaced = true
        return mark
      })
      if (!replaced) {
        break
      }
    }

    /**
     *  - pattern (:label, :label{0-9]+}, ...)
     *  - /* wildcard
     *  - character
     */
    const tokens = markedPath.match(/(?::[^\/]+)|(?:\/\*$)|./g) || []
    for (let i = groups.length - 1; i >= 0; i--) {
      const [mark] = groups[i]
      for (let j = tokens.length - 1; j >= 0; j--) {
        if (tokens[j].indexOf(mark) !== -1) {
          tokens[j] = tokens[j].replace(mark, groups[i][1])
          break
        }
      }
    }

    this.#root.insert(tokens, this.#index, paramAssoc, this.#context, false)
    this.paths[path] = [this.#index++, paramAssoc]
  }

  buildRegExp(): [RegExp, ReplacementMap, ReplacementMap] {
    let regexp = this.#root.buildRegExpStr()
    if (regexp === '') {
      return [/^$/, [], []] // never match
    }

    let captureIndex = 0
    const indexReplacementMap: ReplacementMap = []
    const paramReplacementMap: ReplacementMap = []

    regexp = regexp.replace(/#(\d+)|@(\d+)|\.\*\$/g, (_, handlerIndex, paramIndex) => {
      if (handlerIndex !== undefined) {
        indexReplacementMap[++captureIndex] = Number(handlerIndex)
        return '$()'
      }
      if (paramIndex !== undefined) {
        paramReplacementMap[Number(paramIndex)] = ++captureIndex
        return ''
      }

      return ''
    })

    return [new RegExp(`^${regexp}`), indexReplacementMap, paramReplacementMap]
  }
}

export class SmartRouter<T> implements Router<T> {
  name: string = 'SmartRouter'
  #routers: Router<T>[] = []
  #routes?: [string, string, T][] = []

  constructor(init: { routers: Router<T>[] }) {
    this.#routers = init.routers
  }

  add(method: string, path: string, handler: T) {
    if (!this.#routes) {
      throw new Error(MESSAGE_MATCHER_IS_ALREADY_BUILT)
    }

    this.#routes.push([method, path, handler])
  }

  match(method: string, path: string): Result<T> {
    if (!this.#routes) {
      throw new Error('Fatal error')
    }

    const routers = this.#routers
    const routes = this.#routes

    const len = routers.length
    let i = 0
    let res
    for (; i < len; i++) {
      const router = routers[i]
      try {
        for (let i = 0, len = routes.length; i < len; i++) {
          router.add(...routes[i])
        }
        res = router.match(method, path)
      } catch (e) {
        if (e instanceof UnsupportedPathError) {
          continue
        }
        throw e
      }

      this.match = router.match.bind(router)
      this.#routers = [router]
      this.#routes = undefined
      break
    }

    if (i === len) {
      // not found
      throw new Error('Fatal error')
    }

    // e.g. "SmartRouter + RegExpRouter"
    this.name = `SmartRouter + ${this.activeRouter.name}`

    return res as Result<T>
  }

  get activeRouter(): Router<T> {
    if (this.#routes || this.#routers.length !== 1) {
      throw new Error('No active router has been determined yet.')
    }

    return this.#routers[0]
  }
}

type HandlerSet<T> = {
  handler: T
  possibleKeys: string[]
  score: number
}

type HandlerParamsSet<T> = HandlerSet<T> & {
  params: Record<string, string>
}

insert(method: string, path: string, handler: T): void {
  // eslint-disable-next-line @typescript-eslint/no-this-alias
  let curNode: Node<T> = this
  const parts = splitRoutingPath(path)

  const possibleKeys = new Set<string>()

  let i = 0
  for (const p of parts) {
    const nextP = parts[++i]
    const pattern =
      getPattern(p, nextP) ||
      (nextP === undefined && p && p.indexOf('*') === p.length - 1 ? p : null)
    const isParam = Array.isArray(pattern)
    const key = isParam ? pattern[0] : pattern || p

    const child = (curNode.#children[key] ||= new Node())
    if (pattern && !child.#pattern) {
      child.#pattern = pattern
      curNode.#patterns.push(child)
    }
    curNode = child
    if (isParam) {
      possibleKeys.add(pattern[1])
    }
  }

  curNode.#methods.push({
    [method]: {
      handler,
      possibleKeys: [...possibleKeys],
      score: ++order,
    },
  })
}

#pushHandlerSets(
  handlerSets: HandlerParamsSet<T>[],
  node: Node<T>,
  method: string,
  nodeParams: Record<string, string>,
  params?: Record<string, string>
): void {
  for (let i = 0, len = node.#methods.length; i < len; i++) {
    const m = node.#methods[i]
    const handlerSet = (m[method] || m[METHOD_NAME_ALL]) as HandlerParamsSet<T>
    if (handlerSet) {
      handlerSet.params = createNullObject()
      handlerSets.push(handlerSet)
      for (let i = 0, len = handlerSet.possibleKeys.length; i < len; i++) {
        const key = handlerSet.possibleKeys[i]
        handlerSet.params[key] =
          params?.[key] && !i ? params[key] : (nodeParams[key] ?? params?.[key])
      }
    }
  }
}

