  IsAny<RorO> extends true
    ? {
        [K in P]: {
          [K2 in M as AddDollar<K2>]: {

export type ToSchema<
  M extends string,
  P extends string,
  I extends Input | Input['in'],
  RorO, // Response or Output
> =
  IsAny<RorO> extends true
    ? {
