type AddSchemaIfHasResponse<
  Merged,
  S extends Schema,
  M extends string,
  P extends string,
  I extends Input | Input['in'],
  BasePath extends string,
> = [Merged] extends [Promise<void>] ? S : S & ToSchema<M, MergePath<BasePath, P>, I, Merged>

